// Cloudflare Workers entry (plan §4.1). Rewrite of worker-aia-cdp@5b570aa:src/worker/worker.ts:
// its routing rule (API misses → JSON 404, download-prefix misses → text 404, the rest → ASSETS)
// now lives in the shared app (src/http/ui.ts), which reaches ASSETS only through deps.ui.
// `Env` is the global interface generated by `wrangler types` (worker-configuration.d.ts).
import { createApp } from "../http/app.ts";
import type { App } from "../http/app.ts";
import { ERROR_MESSAGES, errorBody, NO_STORE } from "../http/errors.ts";
import { R2Store } from "../storage/r2.ts";
import { parseSettings } from "./settings.ts";

/**
 * Tokens are optional `wrangler secret`s (not `secrets.required`, which would type them as
 * required and fail deploys while unset); the rest are optional vars with defaults.
 */
type WorkerEnv = Env & {
  AIA_ADMIN_TOKEN?: string;
  AIA_UPLOAD_TOKEN?: string;
  AIA_MAX_UPLOAD_BYTES?: string;
  AIA_TRUST_PROXY?: string;
  AIA_LOG_FORMAT?: string;
};

// One app per env object (stable within an isolate): deps and routes are built once, not per
// request. Invalid settings are not cached, so every request reports them.
const apps = new WeakMap<Env, App>();

function appFor(env: WorkerEnv): { ok: true; app: App } | { ok: false; error: string } {
  const cached = apps.get(env);
  if (cached) {
    return { ok: true, app: cached };
  }
  const parsed = parseSettings({
    AIA_ADMIN_TOKEN: env.AIA_ADMIN_TOKEN,
    AIA_UPLOAD_TOKEN: env.AIA_UPLOAD_TOKEN,
    AIA_MAX_UPLOAD_BYTES: env.AIA_MAX_UPLOAD_BYTES,
    AIA_TRUST_PROXY: env.AIA_TRUST_PROXY,
    AIA_LOG_FORMAT: env.AIA_LOG_FORMAT,
  });
  if (!parsed.ok) {
    return parsed;
  }
  const app = createApp({
    store: new R2Store(env.STORE),
    now: () => new Date(),
    settings: parsed.value.app,
    log: (line) => {
      console.log(line);
    },
    ui: (req) => env.ASSETS.fetch(req),
  });
  apps.set(env, app);
  return { ok: true, app };
}

export default {
  fetch(request, env, ctx) {
    const result = appFor(env);
    if (!result.ok) {
      // JSON regardless of AIA_LOG_FORMAT: the format may be the invalid setting.
      console.log(JSON.stringify({ level: "error", msg: "invalid_settings", error: result.error }));
      return Response.json(errorBody("internal", ERROR_MESSAGES.internal), {
        status: 500,
        headers: NO_STORE,
      });
    }
    return result.app.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<WorkerEnv>;
